/* 首屏：说明 + 可交互材质面板 */
.neumorph-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 380px);
  gap: 48px;
  align-items: center;
}

.neumorph-hero-copy p {
  margin: 0 0 16px;
}

.neumorph-hero-copy p:last-child {
  margin-bottom: 0;
}

.style-body.neumorph .soft-card {
  padding: 32px;
  border-radius: 24px;
  background: #e0e5ec;
  box-shadow: 8px 8px 16px #b8bcc2, -8px -8px 16px #ffffff;
  transition: box-shadow .2s ease-out, transform .2s ease-out;
}

.style-body.neumorph .soft-card:hover {
  box-shadow: 4px 4px 8px #b8bcc2, -4px -4px 8px #ffffff;
  transform: translateY(-2px);
}

.neumorph-demo {
  display: grid;
  gap: 24px;
  justify-items: start;
}

.neumorph-demo-title {
  margin: 0;
  font-weight: 600;
  font-size: 20px;
  line-height: 1.4;
}

.neumorph-demo .raised-btn {
  padding: 12px 24px;
}

/* 凹陷输入框 */
.recessed-field input {
  width: 100%;
  padding: 12px 16px;
  background: #e0e5ec;
  border: none;
  border-radius: 16px;
  font-family: Nunito, system-ui, -apple-system, sans-serif;
  font-size: 14px;
  color: #3d4451;
  box-shadow: inset 8px 8px 16px #b8bcc2, inset -8px -8px 16px #ffffff;
}

.recessed-field input::placeholder {
  color: #7a8494;
}

.recessed-field input:focus {
  outline: none;
  box-shadow: inset 8px 8px 16px rgba(109, 93, 252, 0.3), inset -8px -8px 16px #ffffff;
}

/* 软开关：轨道凹陷、旋钮凸起，开启填紫罗兰 */
.soft-toggle {
  position: relative;
  width: 64px;
  height: 32px;
  padding: 0;
  background: #e0e5ec;
  border: none;
  border-radius: 16px;
  box-shadow: inset 8px 8px 16px #b8bcc2, inset -8px -8px 16px #ffffff;
  cursor: pointer;
}

.soft-toggle-knob {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #e0e5ec;
  box-shadow: 4px 4px 8px #b8bcc2, -4px -4px 8px #ffffff;
  transition: left .2s ease-out, background-color .2s ease-out, box-shadow .2s ease-out;
}

.soft-toggle[aria-checked="true"] .soft-toggle-knob {
  left: 36px;
  background: #6d5dfc;
}

.soft-toggle:focus-visible {
  outline: 3px solid #6d5dfc;
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .soft-toggle-knob {
    transition: none;
  }
}

/* 文档交付件：凹陷预览 + 凸起按钮 */
.style-body.neumorph .lang-toggle {
  background: #e0e5ec;
  border: none;
  border-radius: 16px;
  box-shadow: inset 4px 4px 8px #b8bcc2, inset -4px -4px 8px #ffffff;
}

.style-body.neumorph .lang-toggle button {
  background: transparent;
  border-radius: 12px;
  color: #7a8494;
}

.style-body.neumorph .lang-toggle button[aria-pressed="true"] {
  background: #e0e5ec;
  box-shadow: 4px 4px 8px #b8bcc2, -4px -4px 8px #ffffff;
  color: #6d5dfc;
  font-weight: 600;
}

.style-body.neumorph .takeaway-preview {
  background: #e0e5ec;
  border: none;
  border-radius: 16px;
  box-shadow: inset 8px 8px 16px #b8bcc2, inset -8px -8px 16px #ffffff;
}

/* 目录缩略卡：同色基底上一块凸起面板 */
.neumorph-thumb {
  background: #e0e5ec;
}

.neumorph-thumb-card {
  width: 58%;
  padding: 14px;
  display: grid;
  gap: 10px;
  justify-items: center;
  background: #e0e5ec;
  border-radius: 14px;
  box-shadow: 6px 6px 12px #b8bcc2, -6px -6px 12px #ffffff;
  transition: box-shadow .2s ease-out, transform .2s ease-out;
}

.style-card:hover .neumorph-thumb-card {
  box-shadow: 3px 3px 6px #b8bcc2, -3px -3px 6px #ffffff;
  transform: translateY(-2px);
}

.neumorph-thumb-track {
  position: relative;
  width: 84%;
  height: 18px;
  border-radius: 999px;
  background: #e0e5ec;
  box-shadow: inset 4px 4px 8px #b8bcc2, inset -4px -4px 8px #ffffff;
}

.neumorph-thumb-knob {
  position: absolute;
  top: 2px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #6d5dfc;
  box-shadow: 2px 2px 4px #b8bcc2, -2px -2px 4px #ffffff;
}

.neumorph-thumb-btn {
  padding: 5px 12px;
  border-radius: 9px;
  background: #e0e5ec;
  box-shadow: 4px 4px 8px #b8bcc2, -4px -4px 8px #ffffff;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 8px;
  font-weight: 500;
  color: #3d4451;
}

@media (max-width: 720px) {
  .neumorph-hero {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* ============================ 企业简洁风 ============================ */
/* 克制的商务蓝：浅灰蓝底 + 白卡 + 1px 描边 + 两级阴影，
   焦点环必须带 offset，动效全部不超过 200ms。 */

.style-body.corporate {
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  color: #0f172a;
  gap: 64px;
}

.style-body.corporate a {
  color: #1e40af;
}

.style-body.corporate h1 {
  font-family: Inter, system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-weight: 700;
  font-size: 48px;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.style-body.corporate h1 .style-card-en {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: #1e40af;
}

.style-body.corporate h2 {
  font-family: Inter, system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-weight: 700;
  font-size: 30px;
  line-height: 1.25;
  letter-spacing: -0.01em;
}

.style-body.corporate h3 {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-weight: 600;
  font-size: 16px;
}

.style-body.corporate p {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.65;
}

.style-body.corporate .style-kicker {
  font-weight: 500;
  letter-spacing: 0.04em;
  color: #1e40af;
}

.style-body.corporate .page-lead {
  font-size: 16px;
  color: #0f172a;
}

.style-body.corporate .style-card-tags span {
  border: 1px solid #e5e7eb;
  border-radius: 999px;
  background: #ffffff;
  color: #0f172a;
}

.style-body.corporate .swatch-chip {
  border: 1px solid #e5e7eb;
  border-radius: 8px;
}

.style-body.corporate .style-table th {
  border-bottom: 1px solid #e5e7eb;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  letter-spacing: 0.04em;
  color: #64748b;
}

.style-body.corporate .style-table td {
  border-bottom: 1px solid #e5e7eb;
  font-family: Inter, system-ui, -apple-system, sans-serif;
}

.style-body.corporate .style-body-note,
.style-body.corporate .style-body-comp-role,
.style-body.corporate .takeaway-head p,
.style-body.corporate .takeaway-note,
.style-body.corporate .specimen-meta,
.style-body.corporate .swatch-role {
  color: #64748b;
}

/* Primary Button：企业蓝填充，hover 更深的蓝 + 上浮 2px，active 缩放 0.98 */
.style-body.corporate .source-button,
.style-body.corporate .takeaway-copy,
.primary-btn {
  background: #1e40af;
  border: none;
  border-radius: 8px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  color: #ffffff;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  transition: transform .15s ease-out, box-shadow .15s ease-out, background-color .15s ease-out;
}

.style-body.corporate .source-button:hover,
.style-body.corporate .takeaway-copy:hover,
.primary-btn:hover {
  background: #1e3a8a;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
}

.style-body.corporate .source-button:active,
.style-body.corporate .takeaway-copy:active,
.primary-btn:active {
  transform: scale(0.98);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
}

.style-body.corporate .source-button:focus-visible,
.style-body.corporate .takeaway-copy:focus-visible,
.primary-btn:focus-visible,
.corporate-field input:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #f8fafc, 0 0 0 4px #3b82f6;
}

.style-body.corporate .dl-link:hover {
  color: #1e40af;
}

/* 首屏：说明 + 功能卡 */
.corporate-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 380px);
  gap: 48px;
  align-items: center;
}

.corporate-hero-copy p {
  margin: 0 0 16px;
}

.corporate-hero-copy p:last-child {
  margin-bottom: 0;
}

/* Feature Card：白卡 + 图标块，hover 上浮 + 图标填充企业蓝 */
.feature-card {
  padding: 24px;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  transition: transform .15s ease-out, box-shadow .15s ease-out;
}

.feature-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
}

.feature-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin-bottom: 16px;
  background: #dbeafe;
  border-radius: 12px;
  color: #1e40af;
  transition: background-color .15s ease-out, color .15s ease-out, transform .15s ease-out;
}

.feature-icon svg {
  width: 20px;
  height: 20px;
}

.feature-card:hover .feature-icon {
  background: #1e40af;
  color: #ffffff;
  transform: scale(1.1);
}

.feature-title {
  margin: 0 0 8px;
  font-weight: 600;
  font-size: 20px;
  line-height: 1.4;
}

.feature-body {
  margin: 0;
  font-size: 14px;
  line-height: 1.65;
  color: #64748b;
}

/* Form Input：聚焦企业蓝描边 + 2px 焦点环（2px offset），盒子尺寸不变 */
.corporate-field {
  display: block;
  margin-top: 8px;
  max-width: 360px;
}

.corporate-field > span {
  display: block;
  margin-bottom: 6px;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: #0f172a;
}

.corporate-field input {
  width: 100%;
  padding: 8px 12px;
  background: #ffffff;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 16px;
  color: #0f172a;
  transition: border-color .15s ease-out, box-shadow .15s ease-out;
}

.corporate-field .field-help {
  display: block;
  margin-top: 6px;
  font-size: 12px;
  color: #64748b;
}

.corporate-field input:focus {
  outline: none;
  border-color: #1e40af;
  box-shadow: 0 0 0 2px #f8fafc, 0 0 0 4px #3b82f6;
}

/* Top Navigation 样本 */
.corporate-nav {
  display: flex;
  align-items: center;
  gap: 24px;
  margin-top: 8px;
  padding: 12px 20px;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-bottom: 1px solid #e5e7eb;
  border-radius: 8px;
}

.corporate-nav-brand {
  font-weight: 600;
  font-size: 18px;
  color: #0f172a;
  margin-right: auto;
}

.corporate-nav-links {
  display: flex;
  gap: 24px;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: #64748b;
}

.corporate-nav-links span {
  transition: color .15s ease-out, transform .15s ease-out;
}

.corporate-nav-links span:hover {
  color: #0f172a;
  transform: translateY(-1px);
}

/* Status Badge：圆点 + 色底，不只靠颜色传达 */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 8px;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  background: #dbeafe;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: #1e40af;
}

.status-badge-ok {
  background: #d1fae5;
  color: #10b981;
}

.status-badge-hint {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  color: #c559f0;
}

.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

/* 文档交付件：白卡 + 细描边 */
.style-body.corporate .lang-toggle {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
}

.style-body.corporate .lang-toggle button[aria-pressed="true"] {
  background: #1e40af;
  color: #ffffff;
  border-radius: 6px;
}

.style-body.corporate .takeaway-preview {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}

/* 目录缩略卡：mist 底上一张白卡 + 图标块 + 徽标 */
.corporate-thumb {
  background: #f8fafc;
}

.corporate-thumb-card {
  width: 66%;
  padding: 14px;
  display: grid;
  gap: 10px;
  justify-items: start;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  transition: transform .15s ease-out, box-shadow .15s ease-out;
}

.style-card:hover .corporate-thumb-card {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
}

.corporate-thumb-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 7px;
  background: #dbeafe;
  color: #1e40af;
  transition: background-color .15s ease-out, color .15s ease-out;
}

.style-card:hover .corporate-thumb-icon {
  background: #1e40af;
  color: #ffffff;
}

.corporate-thumb-icon svg {
  width: 12px;
  height: 12px;
}

.corporate-thumb-bar {
  width: 82%;
  height: 7px;
  border-radius: 4px;
  background: #0f172a;
}

.corporate-thumb-line {
  width: 92%;
  height: 4px;
  border-radius: 3px;
  background: #e5e7eb;
}

.corporate-thumb-badge {
  padding: 2px 8px;
  border-radius: 999px;
  background: #dbeafe;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 7px;
  font-weight: 500;
  color: #1e40af;
}

@media (max-width: 720px) {
  .corporate-hero {
    grid-template-columns: minmax(0, 1fr);
  }
}

