}

.flat-btn-outline:focus-visible {
  outline: 2px solid #ff3366;
  outline-offset: 4px;
}

/* Flat Card：hover 整卡反转，不做位移 */
.flat-card {
  padding: 32px;
  background: #ffffff;
  border: 2px solid #000000;
  border-radius: 0;
  display: grid;
  gap: 16px;
  justify-items: start;
  transition: background-color .2s ease, color .2s ease;
}

.flat-card:hover {
  background: #000000;
  color: #ffffff;
}

.flat-demo-title {
  margin: 0;
  font-weight: 900;
  font-size: 24px;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.flat-demo-body {
  margin: 0;
  font-size: 16px;
  line-height: 1.6;
}

/* Accent Label：黑底白字 / 亮黄底黑字 / 薄荷青底白字 */
.accent-label {
  display: inline-block;
  padding: 4px 8px;
  background: #000000;
  color: #ffffff;
  border-radius: 0;
  font-family: "Helvetica Neue", Arial, system-ui, sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.accent-label-yellow {
  background: #ffcc00;
  color: #000000;
}

.accent-label-mint {
  background: #00d4aa;
  color: #ffffff;
}

