/* Masonry Card：无阴影，hover 只有图片动 */
.masonry-card {
  break-inside: avoid;
  margin: 0 0 16px;
  background: #ffffff;
  border: 1px solid #e8e8e8;
  border-radius: 16px;
  padding: 16px;
}

.masonry-media {
  position: relative;
  display: block;
  border-radius: 12px;
  overflow: hidden;
}

.masonry-photo {
  display: block;
  height: 220px;
  transition: transform .4s ease-out;
}

/* 图片占位：正式接入时替换为真实图片 */
.masonry-photo::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 90% at 18% 12%, rgba(255, 255, 255, 0.32), transparent 55%);
}

.masonry-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: #000000;
  opacity: 0;
  transition: opacity .4s ease-out;
  pointer-events: none;
}

.masonry-card:hover .masonry-photo {
  transform: scale(1.05);
}

.masonry-card:hover .masonry-media::after {
  opacity: 0.04;
}

