/* 实演前的两段说明 */
.scene-intro {
  max-width: 76ch;
}

.scene-intro p {
  margin: 0 0 16px;
}

.scene-intro p:last-child {
  margin-bottom: 0;
}

/* 演示视口：一个固定高度的 scroll-snap 容器，真机上为全屏 */
.snap-stage {
  position: relative;
  height: 560px;
  overflow-y: auto;
  scroll-snap-type: y mandatory;
  scroll-behavior: smooth;
  overscroll-behavior: contain;
  border: 1px solid #26262b;
  border-radius: 20px;
  scrollbar-width: none;
}

.snap-stage::-webkit-scrollbar {
  display: none;
}

/* 场景结构规则限定在舞台内，避免与页面级类名冲突 */
.snap-stage .scene {
  height: 100%;
  scroll-snap-align: start;
  scroll-snap-stop: always;
  display: grid;
  place-items: center;
}

.scene--ink {
  background: #000000;
  color: #ffffff;
}

.scene--paper {
  background: #ffffff;
  color: #18181b;
}

.scene--turn {
  background: #000000;
  color: #ffffff;
}

.scene-inner {
  display: grid;
  justify-items: start;
  gap: 24px;
  width: 100%;
  max-width: 720px;
  padding: 48px;
}

.scene-label {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.scene--ink .scene-label {
  color: #6366f1;
}

.scene--paper .scene-label {
  color: #14b8a6;
}

.scene--turn .scene-label {
  color: #ec4899;
}

.scene-title {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 44px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.025em;
}

.scene-body {
  margin: 0;
  max-width: 40ch;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 18px;
  line-height: 1.55;
}

.scene--ink .scene-body,
.scene--turn .scene-body {
  color: #a1a1aa;
}

.scene--paper .scene-body {
  color: #52525b;
}

.scene-stat {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 18px;
  color: #52525b;
}

.scene-stat strong {
  margin-right: 8px;
  font-size: 44px;
  font-weight: 700;
  color: #14b8a6;
}

/* Scene CTA：靛蓝胶囊，转折场景用品红变体 */
.scene-cta {
  padding: 14px 32px;
  background: #6366f1;
  border: none;
  border-radius: 999px;
  box-shadow: 0 8px 20px rgba(99, 102, 241, 0.30);
  color: #ffffff;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition: transform .2s ease-out, box-shadow .2s ease-out, background-color .2s ease-out;
}

.scene-cta:hover {
  background: #7378f2;
  transform: translateY(-2px);
}

.scene-cta:active {
  transform: scale(0.98);
}

.scene-cta:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

.scene-cta--turn {
  background: #ec4899;
  box-shadow: 0 8px 20px rgba(236, 72, 153, 0.30);
}

.scene-cta--turn:hover {
  background: #f472b6;
}

.scene-comp-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px;
  margin: 0;
}

/* Staggered Reveal：延迟变量由脚本按 80ms 步进钉上，离场不延迟 */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity .6s ease-out, transform .6s ease-out;
}

.scene.is-in .reveal {
  opacity: 1;
  transform: none;
  transition-delay: var(--d, 0ms);
}

/* Scene Progress：右侧竖排圆点，当前拉伸为靛蓝短竖条 */
.scene-dots {
  position: absolute;
  top: 50%;
  right: 16px;
  display: grid;
  gap: 12px;
  transform: translateY(-50%);
}

.scene-dot {
  width: 8px;
  height: 8px;
  padding: 0;
  background: rgba(255, 255, 255, 0.30);
  border: none;
  border-radius: 999px;
  cursor: pointer;
  transition: height .2s ease-out, background-color .2s ease-out;
}

.scene-dot.is-on {
  height: 24px;
  background: #6366f1;
}

.scene-dot:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

/* Scroll Cue：底部居中，2 秒往复淡入淡出；最后一场转「回到顶部」 */
.scene-cue {
  position: absolute;
  bottom: 24px;
  left: 50%;
  display: grid;
  justify-items: center;
  gap: 6px;
  padding: 8px 12px;
  background: none;
  border: none;
  color: #ffffff;
  cursor: pointer;
  transform: translateX(-50%);
  mix-blend-mode: difference;
  animation: scene-cue-pulse 2s ease-in-out infinite;
}

.scene-cue-arrow {
  width: 24px;
  height: 24px;
  transition: transform .2s ease-out;
}

.scene-cue[data-last="true"] .scene-cue-arrow {
  transform: rotate(180deg);
}

.scene-cue-text {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

@keyframes scene-cue-pulse {
  0%, 100% {
    opacity: 0.25;
  }

  50% {
    opacity: 1;
  }
}

.scene-stage-note {
  margin: 12px 0 0;
  font-size: 13px;
}

@media (max-width: 650px) {
  .snap-stage {
    height: 480px;
  }

  .scene-inner {
    padding: 32px;
  }

  .scene-title {
    font-size: 32px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .snap-stage {
    scroll-behavior: auto;
  }

  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .scene-cue {
    animation: none;
  }

  .scene-cta,
  .style-body.fullscroll .source-button,
  .style-body.fullscroll .takeaway-copy {
    transition: none;
  }

  .scene-cta:hover,
  .style-body.fullscroll .source-button:hover,
  .style-body.fullscroll .takeaway-copy:hover {
    transform: none;
  }
}

