/* Glass Panel 演示卡：三层阴影 + hover 升档，500ms 慢过渡 */
.glass-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 48px;
  align-items: center;
}

.glass-hero-copy p {
  margin: 0 0 16px;
  font-size: 15px;
}

.glass-hero-copy p:last-child {
  margin-bottom: 0;
}

.glass-demo {
  display: grid;
  justify-items: center;
}

.glass-panel-demo {
  width: min(100%, 360px);
  padding: 32px;
  display: grid;
  gap: 10px;
  justify-items: start;
  background: rgba(255, 255, 255, 0.08);
  -webkit-backdrop-filter: blur(40px) saturate(180%);
  backdrop-filter: blur(40px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 24px;
  box-shadow:
    0 16px 40px rgba(3, 7, 18, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    inset 0 -1px 0 rgba(2, 6, 16, 0.35);
  transition: fill 0.5s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.5s cubic-bezier(0.16, 1, 0.3, 1), transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.glass-panel-demo:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.30);
  transform: translateY(-2px);
  box-shadow:
    0 24px 64px rgba(3, 7, 18, 0.6),
    inset 0 1px 0 rgba(255, 255, 255, 0.32),
    inset 0 -1px 0 rgba(2, 6, 16, 0.35);
}

.glass-label {
  font-family: Inter, system-ui, sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #7c9cc4;
}

.glass-demo-title {
  margin: 0;
  font-family: Inter, system-ui, sans-serif;
  font-size: 32px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: #ffffff;
}

.glass-demo-body {
  margin: 0 0 8px;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.72);
}

/* Champagne CTA：全站唯一强调色 */
.style-body.glass .source-button,
.style-body.glass .takeaway-copy,
.champagne-btn {
  background: #e4b863;
  border: none;
  border-radius: 999px;
  box-shadow: 0 8px 24px rgba(228, 184, 99, 0.18);
  color: #060a13;
  font-family: Inter, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
  transition: box-shadow 0.5s cubic-bezier(0.16, 1, 0.3, 1), transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.style-body.glass .source-button:hover,
.style-body.glass .takeaway-copy:hover,
.champagne-btn:hover {
  opacity: 0.92;
  transform: translateY(-1px);
  box-shadow: 0 12px 32px rgba(228, 184, 99, 0.25);
}

.style-body.glass .source-button:active,
.style-body.glass .takeaway-copy:active,
.champagne-btn:active {
  transform: translateY(0);
  opacity: 1;
}

.style-body.glass .source-button:focus-visible,
.style-body.glass .takeaway-copy:focus-visible,
.champagne-btn:focus-visible {
  outline: 2px solid #e4b863;
  outline-offset: 2px;
}

.champagne-btn--sm {
  padding: 8px 18px;
  font-size: 12px;
}

/* Glass Input / Stat Tile / Night Nav 演示 */
.glass-field {
  display: grid;
  gap: 6px;
  width: min(100%, 300px);
}

.glass-field span {
  font-family: Inter, system-ui, sans-serif;
