  font-weight: 600;
  font-size: 16px;
  color: #e2e8f0;
}

.style-body.darkmode p {
  font-family: Inter, system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 14px;
  line-height: 1.6;
  color: #94a3b8;
}

.style-body.darkmode .style-kicker {
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}

.style-body.darkmode .page-lead {
  font-size: 16px;
  color: #e2e8f0;
}

.style-body.darkmode .style-card-tags span {
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 999px;
  background: rgba(30, 41, 59, 0.6);
