/* Glitch Heading：两个伪元素副本做错位 */
.cyber-glitch {
  position: relative;
}

.cyber-glitch::before,
.cyber-glitch::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  mix-blend-mode: screen;
  opacity: 0.7;
  pointer-events: none;
  transition: transform .06s steps(2);
}

.cyber-glitch::before {
  color: #ff0506;
  transform: translate(-2px, 0);
}

.cyber-glitch::after {
  color: #00ffff;
  transform: translate(2px, 0);
}

.cyber-glitch:hover::before {
  transform: translate(-4px, 1px);
}

.cyber-glitch:hover::after {
  transform: translate(4px, -1px);
}

