/* Sunburst Divider：水平金线 + 向下辐射短线 */
.deco-sunburst {
  position: relative;
  width: 160px;
  height: 26px;
  margin: 8px auto 0;
}

.deco-sunburst::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 1px;
  background: #d4af37;
}

.deco-sunburst i {
  position: absolute;
  top: 0;
  width: 1px;
  height: 12px;
  background: #d4af37;
  transform-origin: top center;
}

.deco-sunburst i:nth-child(1) { left: 12%; transform: rotate(24deg); height: 9px; }
.deco-sunburst i:nth-child(2) { left: 24%; transform: rotate(18deg); height: 10px; }
.deco-sunburst i:nth-child(3) { left: 36%; transform: rotate(12deg); height: 11px; }
.deco-sunburst i:nth-child(4) { left: 50%; transform: rotate(0deg); height: 12px; }
.deco-sunburst i:nth-child(5) { left: 64%; transform: rotate(-12deg); height: 11px; }
.deco-sunburst i:nth-child(6) { left: 76%; transform: rotate(-18deg); height: 10px; }
.deco-sunburst i:nth-child(7) { left: 88%; transform: rotate(-24deg); height: 9px; }

