.vtl {
  position: relative;
  max-width: 720px;
  margin: 0 auto;
  display: grid;
  gap: 48px;
}

/* 连接线：从第一节点画到最后节点，2px 板岩 25% */
.vtl::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 10px;
  bottom: 10px;
  width: 2px;
  transform: translateX(-50%);
  background: rgba(30, 41, 59, 0.25);
}

.vtl-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 20px minmax(0, 1fr);
  gap: 24px;
  align-items: center;
}

.vtl-node {
  width: 20px;
  height: 20px;
  border-radius: 999px;
  background: #ffffff;
