  color: #ff00ff;
}

.style-body.glitch h1 {
  font-weight: 900;
  font-size: 32px;
  line-height: 1;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #ffffff;
  position: relative;
}

.style-body.glitch h1 .style-card-en {
  font-size: 12px;
  letter-spacing: 0.16em;
  color: #ffff00;
}

.glitch-split::before,
.glitch-split::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  opacity: 0.8;
  pointer-events: none;
  transition: none;
}

.glitch-split::before {
  color: #ff00ff;
  transform: translate(-3px, 0);
}

.glitch-split::after {
  color: #00ffff;
  transform: translate(3px, 0);
}

.glitch-split:hover::before {
  transform: translate(-6px, -1px);
}

.glitch-split:hover::after {
  transform: translate(6px, 1px);
}

