.canime-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 48px;
  align-items: center;
}

.canime-hero-copy p {
  margin: 0 0 14px;
  font-size: 13px;
}

.canime-hero-copy p:last-child {
  margin-bottom: 0;
}

.canime-demo {
  display: grid;
  justify-items: center;
}

.canime-panel-demo {
  position: relative;
  width: min(100%, 350px);
  padding: 24px;
  display: grid;
  gap: 12px;
  justify-items: start;
  background: rgba(124, 58, 237, 0.08);
  border: 1px solid rgba(124, 58, 237, 0.40);
  border-radius: 0;
  box-shadow: 0 0 12px #7c3aed, 0 0 24px rgba(6, 214, 160, 0.35), 0 0 48px rgba(255, 0, 110, 0.20);
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  transition: box-shadow .22s ease-out, transform .22s ease-out;
}

.canime-panel-demo:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 18px #7c3aed, 0 0 36px rgba(6, 214, 160, 0.45), 0 0 72px rgba(255, 0, 110, 0.30);
}

.canime-bracket {
  position: absolute;
  width: 16px;
  height: 16px;
  border-color: #7c3aed;
  border-style: solid;
  border-width: 0;
}

.canime-bracket--tl { left: 0; top: 0; border-left-width: 2px; border-top-width: 2px; }
.canime-bracket--tr { right: 12px; top: 0; border-right-width: 2px; border-top-width: 2px; }
.canime-bracket--bl { left: 0; bottom: 12px; border-left-width: 2px; border-bottom-width: 2px; }
.canime-bracket--br { right: 12px; bottom: 12px; border-right-width: 2px; border-bottom-width: 2px; }

.canime-panel-tag {
  margin: 0;
  font-family: ui-monospace, "JetBrains Mono", monospace;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #06d6a0;
}

.canime-demo-title {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #e8e6f5;
}

.canime-readout {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 28px;
  border: 1px solid rgba(124, 58, 237, 0.25);
  padding: 0 10px;
}

.canime-readout-label {
  font-family: ui-monospace, "JetBrains Mono", monospace;
  font-size: 11px;
  letter-spacing: 0.16em;
  color: #e8e6f5;
}

.canime-readout-bar {
  flex: 1;
  display: flex;
  gap: 2px;
  height: 12px;
}

.canime-readout-bar i {
  flex: 1;
  background: #06d6a0;
}

.canime-readout-bar i:nth-child(n+9) {
  background: #ff006e;
}

.canime-readout-val {
  font-family: ui-monospace, "JetBrains Mono", monospace;
  font-size: 12px;
  color: #06d6a0;
}

.style-body.canime .source-button,
.style-body.canime .takeaway-copy,
.canime-btn {
  background: #7c3aed;
  border: 1px solid rgba(81, 177, 255, 0.30);
  border-radius: 0;
  box-shadow: 0 0 12px #7c3aed, 0 0 24px rgba(6, 214, 160, 0.35), 0 0 48px rgba(255, 0, 110, 0.20);
  color: #ffffff;
  font-family: ui-monospace, "JetBrains Mono", monospace;
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding: 12px 28px;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  transition: background-color .18s ease-out, box-shadow .18s ease-out, transform .18s ease-out;
}

.style-body.canime .source-button:hover,
.style-body.canime .takeaway-copy:hover,
.canime-btn:hover {
  background: #8b4ff5;
  box-shadow: 0 0 18px #7c3aed, 0 0 36px rgba(6, 214, 160, 0.45), 0 0 72px rgba(255, 0, 110, 0.30);
}

.style-body.canime .source-button:active,
.style-body.canime .takeaway-copy:active,
.canime-btn:active {
  transform: translateY(1px);
  box-shadow: 0 0 8px #7c3aed, 0 0 16px rgba(6, 214, 160, 0.30), 0 0 28px rgba(255, 0, 110, 0.18);
}

.style-body.canime .source-button:focus-visible,
.style-body.canime .takeaway-copy:focus-visible,
.canime-btn:focus-visible {
  outline: 2px solid #06d6a0;
  outline-offset: 3px;
}

/* 字体现身样本 */
.style-body.canime .type-specimen .canime-specimen-title {
  margin: 0 0 8px;
  font-weight: 700;
  font-size: 20px;
  line-height: 1.15;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #e8e6f5;
}

.style-body.canime .type-specimen .canime-specimen-label {
  margin: 0 0 8px;
  font-family: ui-monospace, "JetBrains Mono", monospace;
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #06d6a0;
}

/* 文档交付件 */
.style-body.canime .lang-toggle {
  background: rgba(124, 58, 237, 0.08);
  border: 1px solid rgba(124, 58, 237, 0.4);
  border-radius: 0;
}

.style-body.canime .lang-toggle button {
  border-radius: 0;
  color: rgba(232, 230, 245, 0.7);
  font-weight: 600;
}

.style-body.canime .lang-toggle button[aria-pressed="true"] {
  background: #7c3aed;
  color: #ffffff;
}

.style-body.canime .takeaway-preview {
  background: rgba(124, 58, 237, 0.08);
  border: 1px solid rgba(124, 58, 237, 0.3);
  border-radius: 0;
  color: rgba(232, 230, 245, 0.9);
}

@media (max-width: 900px) {
  .canime-hero {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* 目录缩略卡：六边形底 + 支架小面板 */
.canime-thumb {
  background:
    repeating-linear-gradient(60deg, rgba(124, 58, 237, 0.10) 0 1px, transparent 1px 10px),
    repeating-linear-gradient(-60deg, rgba(124, 58, 237, 0.10) 0 1px, transparent 1px 10px),
    #0f0f1a;
}

.canime-thumb-panel {
  position: absolute;
  left: 20%;
  bottom: 28px;
  width: 60%;
  padding: 12px;
  display: grid;
  gap: 7px;
  background: rgba(124, 58, 237, 0.10);
  border: 1px solid rgba(124, 58, 237, 0.5);
  border-radius: 0;
  box-shadow: 0 0 10px #7c3aed, 0 0 18px rgba(6, 214, 160, 0.3);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}

.canime-thumb-bar {
  width: 72%;
  height: 6px;
  background: #7c3aed;
}

.canime-thumb-gauge {
  display: flex;
  gap: 2px;
  height: 8px;
}

.canime-thumb-gauge i {
  flex: 1;
  background: #06d6a0;
}

.canime-thumb-gauge i:nth-child(n+7) {
  background: #ff006e;
}




/* ============================ 像素动漫风 ============================ */

.style-body.panime {
  --panime-blue: #4a90d9;
  --panime-purple: #2d1b69;
  --panime-dialog: #1a1038;
  --panime-red: #ff6b6b;
  --panime-gold: #ffd93d;
  --panime-green: #50c878;
  --panime-olive: #a98d16;
  --panime-mono: 'Press Start 2P', 'Courier New', ui-monospace, monospace;
  background: var(--panime-purple);
  color: #ffffff;
}

.style-body.panime h1,
.style-body.panime h2,
.style-body.panime h3 {
  font-family: var(--panime-mono);
  letter-spacing: 0.05em;
}

.style-body.panime h1 { text-shadow: none; }
.style-body.panime h2 { border-bottom: 4px solid var(--panime-blue); padding-bottom: 12px; }
.style-body.panime h3 { letter-spacing: 0.05em; }

.style-body.panime p,
.style-body.panime li {
  line-height: 1.8;
}

.style-body.panime .style-kicker {
  color: var(--panime-gold);
  font-family: var(--panime-mono);
  letter-spacing: 0.12em;
}

.style-body.panime .style-card-en {
  color: var(--panime-gold);
}

.style-body.panime .style-card-tags span {
  border-radius: 0;
  background: var(--panime-dialog);
  border: 1px solid rgba(74, 144, 217, 0.5);
  color: #e8e6f5;
  font-family: var(--panime-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
}

.style-body.panime .palette-name,
.style-body.panime .swatch-role {
  color: rgba(255, 255, 255, 0.72);
}

.style-body.panime .swatch-chip,
.style-body.panime code {
  border-radius: 0;
}

.style-body.panime .swatch-chip {
  border: 4px solid var(--panime-dialog);
  box-shadow: none;
}

.style-body.panime code {
  background: var(--panime-dialog);
  border: 1px solid rgba(74, 144, 217, 0.35);
  color: var(--panime-gold);
}

.style-body.panime .style-table {
  background: var(--panime-dialog);
  border: 2px solid rgba(74, 144, 217, 0.4);
  border-radius: 0;
}

.style-body.panime .style-table th {
  background: rgba(74, 144, 217, 0.18);
  color: var(--panime-gold);
  border-bottom: 2px solid rgba(74, 144, 217, 0.4);
}

.style-body.panime .style-table td {
  border-top: 1px solid rgba(74, 144, 217, 0.22);
}

.style-body.panime .specimen-meta,
.style-body.panime .style-body-note {
  color: rgba(255, 255, 255, 0.66);
}

.style-body.panime .type-specimen {
  background: var(--panime-dialog);
  border: 2px solid rgba(74, 144, 217, 0.4);
  border-radius: 0;
}

.style-body.panime .dos-donts {
  background: var(--panime-dialog);
  border: 2px solid rgba(74, 144, 217, 0.4);
  border-radius: 0;
}

.style-body.panime .dos-donts li::before {
  color: var(--panime-gold);
}

.style-body.panime .dos-donts > div:last-child li::before {
  color: var(--panime-red);
}

.style-body.panime .takeaway-preview,
.style-body.panime .lang-toggle button,
.style-body.panime .takeaway-copy {
  border-radius: 0;
}

.style-body.panime .takeaway-preview {
  background: var(--panime-dialog);
  border: 2px solid rgba(74, 144, 217, 0.4);
  color: rgba(255, 255, 255, 0.82);
}

.style-body.panime .lang-toggle button {
  background: var(--panime-dialog);
  border: 2px solid rgba(74, 144, 217, 0.4);
  color: rgba(255, 255, 255, 0.72);
  font-family: var(--panime-mono);
  font-size: 10px;
}

.style-body.panime .lang-toggle button[aria-pressed="true"] {
  background: var(--panime-blue);
  border-color: var(--panime-blue);
  color: #ffffff;
}

.style-body.panime .takeaway-copy {
  background: var(--panime-blue);
  border: 4px solid var(--panime-purple);
  border-radius: 0;
  color: #ffffff;
  font-family: var(--panime-mono);
  font-size: 12px;
  letter-spacing: 0.08em;
  box-shadow: 4px 4px 0 var(--panime-dialog);
  transition: none;
}

.style-body.panime .takeaway-copy:hover {
  background: var(--panime-gold);
  color: var(--panime-purple);
}

.style-body.panime .takeaway-copy:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.style-body.panime .source-button {
  border-radius: 0;
  font-family: var(--panime-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
}

/* -- hero：对话框演示 -- */

.panime-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 32px;
  align-items: start;
  margin-bottom: 64px;
}

.panime-hero-copy p {
  margin-bottom: 16px;
}

.panime-demo {
  padding-top: 8px;
}

.panime-dialog-demo {
  position: relative;
  background: var(--panime-dialog);
  border: 4px solid var(--panime-blue);
  border-radius: 0;
  padding: 20px;
  box-shadow: 4px 4px 0 var(--panime-dialog), 4px 4px 0 4px rgba(0, 0, 0, 0.35);
}

.panime-corner {
  position: absolute;
  width: 8px;
  height: 8px;
  background: var(--panime-blue);
}

.panime-corner--tl { top: 4px; left: 4px; }
.panime-corner--tr { top: 4px; right: 4px; }
.panime-corner--bl { bottom: 4px; left: 4px; }
.panime-corner--br { bottom: 4px; right: 4px; }

.panime-dialog-text {
  font-family: var(--panime-mono);
  font-size: 14px;
  line-height: 1.8;
  color: #ffffff;
  margin: 0 0 16px;
}

.panime-status-demo {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.panime-status-label {
  font-family: var(--panime-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--panime-gold);
  width: 40px;
}

.panime-status-bar {
  display: flex;
  gap: 2px;
  flex: 1;
  height: 12px;
  padding: 2px;
  border: 4px solid var(--panime-purple);
  background: rgba(0, 0, 0, 0.35);
  box-sizing: content-box;
}

.panime-status-bar i {
  flex: 1;
  background: var(--panime-green);
}

.panime-status-demo--exp .panime-status-bar i {
  background: var(--panime-gold);
}

.panime-status-bar i.is-empty {
  background: rgba(255, 255, 255, 0.12);
}

.panime-status-val {
  font-family: var(--panime-mono);
  font-size: 10px;
  color: #ffffff;
  white-space: nowrap;
}

.panime-demo-actions {
  display: flex;
  gap: 12px;
  margin-top: 16px;
}

.panime-btn {
  display: inline-block;
  background: var(--panime-blue);
  border: 4px solid var(--panime-purple);
  border-radius: 0;
  color: #ffffff;
  font-family: var(--panime-mono);
  font-size: 12px;
  letter-spacing: 0.08em;
  padding: 12px 24px;
  box-shadow: 4px 4px 0 var(--panime-purple);
  cursor: pointer;
  transition: none;
}

.panime-btn:hover {
  background: var(--panime-gold);
  color: var(--panime-purple);
}

.panime-btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.panime-btn--ghost {
  background: transparent;
  border-color: rgba(74, 144, 217, 0.5);
  color: rgba(255, 255, 255, 0.85);
  box-shadow: none;
}

.panime-btn--ghost:hover {
  background: rgba(74, 144, 217, 0.2);
  color: var(--panime-gold);
}

.panime-btn--ghost:active {
  transform: translate(4px, 4px);
}

.panime-specimen-title {
  font-family: var(--panime-mono);
  font-size: 20px;
  letter-spacing: 0.05em;
  color: var(--panime-gold);
}

.panime-sparkle {
  display: grid;
  grid-template-columns: repeat(2, 12px);
  gap: 4px;
  width: max-content;
}

.panime-sparkle i {
  width: 12px;
  height: 12px;
  background: var(--panime-gold);
}

.panime-sparkle i:nth-child(2),
.panime-sparkle i:nth-child(3) {
  background: var(--panime-blue);
}

.panime-menu {
  list-style: none;
  margin: 0;
  padding: 0;
  max-width: 320px;
}

.panime-menu li {
  position: relative;
  height: 32px;
  line-height: 32px;
  padding-left: 24px;
  font-family: var(--panime-mono);
  font-size: 12px;
  color: rgba(255, 255, 255, 0.72);
  border-radius: 0;
}

.panime-menu li::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 12px;
  width: 8px;
  height: 8px;
  background: transparent;
}

.panime-menu li.is-active {
  background: rgba(74, 144, 217, 0.2);
  color: var(--panime-gold);
}

.panime-menu li.is-active::before {
  background: var(--panime-gold);
}

@media (max-width: 900px) {
  .panime-hero {
    grid-template-columns: 1fr;
  }
}

/* -- 目录缩略图 -- */

.style-card .panime-thumb {
  background: var(--panime-purple);
}

.panime-thumb-dialog {
  position: relative;
  display: block;
  width: 70%;
  background: var(--panime-dialog);
  border: 3px solid var(--panime-blue);
  padding: 14px 12px 12px;
}

.panime-thumb-dialog::before,
.panime-thumb-dialog::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 6px;
  background: var(--panime-blue);
}

.panime-thumb-dialog::before { top: 3px; left: 3px; }
.panime-thumb-dialog::after { bottom: 3px; right: 3px; }

.panime-thumb-line {
  display: block;
  height: 6px;
  background: rgba(255, 255, 255, 0.65);
  margin-bottom: 6px;
}

.panime-thumb-line--short {
  width: 60%;
  margin-bottom: 10px;
}

.panime-thumb-hp {
  display: flex;
  gap: 2px;
  height: 8px;
}

.panime-thumb-hp i {
  flex: 1;
  background: var(--panime-green);
}

.panime-thumb-hp i:nth-child(n+8) {
  background: rgba(255, 255, 255, 0.14);
}
/* ============================ 日系清新风 ============================ */

.style-body.jfresh {
  --jfresh-ink: #4a4a46;
  --jfresh-paper: #fafaf8;
  --jfresh-line: rgba(212, 212, 207, 0.30);
  --jfresh-line-strong: rgba(212, 212, 207, 0.60);
  --jfresh-blue: #64b5f6;
  --jfresh-mint: #98d8c8;
  --jfresh-sakura: #ffb7c5;
  --jfresh-mist: #b8d4e3;
  background: var(--jfresh-paper);
  color: var(--jfresh-ink);
}

.style-body.jfresh h1,
.style-body.jfresh h2,
.style-body.jfresh h3 {
  font-weight: 200;
  letter-spacing: 0.02em;
}

.style-body.jfresh h2 {
  font-weight: 300;
  border-bottom: 1px solid var(--jfresh-line);
  padding-bottom: 16px;
}

.style-body.jfresh h3 {
  font-weight: 300;
}

.style-body.jfresh p,
.style-body.jfresh li {
  font-weight: 300;
  line-height: 1.9;
}

.style-body.jfresh .style-kicker {
  color: var(--jfresh-blue);
  font-weight: 300;
  letter-spacing: 0.1em;
}

.style-body.jfresh .style-card-en {
