  background: #ffffff;
  border: 1px solid var(--jfresh-line);
  color: var(--jfresh-ink);
  font-weight: 300;
}

.style-body.jfresh .style-table {
  background: #ffffff;
  border: 1px solid var(--jfresh-line);
  border-radius: 12px;
  box-shadow: none;
}

.style-body.jfresh .style-table th {
  background: transparent;
  color: var(--jfresh-ink);
  font-weight: 300;
  border-bottom: 1px solid var(--jfresh-line);
}

.style-body.jfresh .style-table td {
  border-top: 1px solid var(--jfresh-line);
}

.style-body.jfresh .specimen-meta,
.style-body.jfresh .style-body-note {
  color: rgba(74, 74, 70, 0.62);
}

.style-body.jfresh .type-specimen {
  background: #ffffff;
  border: 1px solid var(--jfresh-line);
  border-radius: 12px;
  box-shadow: none;
}

.style-body.jfresh .dos-donts {
  background: #ffffff;
  border: 1px solid var(--jfresh-line);
  border-radius: 12px;
  box-shadow: none;
}

.style-body.jfresh .dos-donts li::before {
  color: var(--jfresh-mint);
}

.style-body.jfresh .dos-donts > div:last-child li::before {
  color: var(--jfresh-sakura);
}

.style-body.jfresh .takeaway-preview {
  background: #ffffff;
  border: 1px solid var(--jfresh-line);
  border-radius: 12px;
  color: rgba(74, 74, 70, 0.82);
}

.style-body.jfresh .lang-toggle button {
  background: transparent;
  border: 1px solid var(--jfresh-line);
  border-radius: 8px;
  color: rgba(74, 74, 70, 0.72);
  font-weight: 300;
  transition: all 500ms ease;
}

.style-body.jfresh .lang-toggle button[aria-pressed="true"] {
  background: var(--jfresh-blue);
  border-color: var(--jfresh-blue);
  color: #ffffff;
}

.style-body.jfresh .takeaway-copy {
  background: transparent;
  border: 1px solid var(--jfresh-line);
  border-radius: 8px;
  color: var(--jfresh-ink);
  font-weight: 300;
  box-shadow: none;
  transition: all 500ms ease;
}

.style-body.jfresh .takeaway-copy:hover {
  border-color: var(--jfresh-blue);
  color: var(--jfresh-blue);
}

.style-body.jfresh .source-button {
  border-radius: 8px;
  font-weight: 300;
}

/* -- hero：Ma 卡片演示 -- */

.jfresh-hero {
