}

.asym-stage {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 2.2fr 0.6fr;
  gap: 16px;
  margin-top: 32px;
  min-height: 320px;
}

.asym-headline {
  position: absolute;
  top: -8px;
  left: 8px;
  font-size: clamp(64px, 9vw, 120px);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--asym-ink);
  z-index: 30;
  pointer-events: none;
}

.asym-red-block {
  position: relative;
  background: var(--asym-red);
  color: #ffffff;
  padding: 24px;
  margin-top: 96px;
  transform: translate(-32px, -16px);
  z-index: 20;
  box-shadow: 6px 6px 0 var(--asym-ink);
}

.asym-mid-block {
