  max-width: 62em;
}

.psec-stage {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 24px;
  margin-top: 32px;
}

.psec-frame {
  position: relative;
  min-height: 300px;
  border-radius: 24px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.psec-frame--dark {
  background:
    radial-gradient(120% 90% at 20% 0%, #2b4a73 0%, #1e3a5f 45%, #12253e 100%);
}

.psec-frame-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(115deg, transparent 42%, rgba(148, 197, 253, 0.10) 43%, transparent 44%),
    linear-gradient(65deg, transparent 58%, rgba(148, 197, 253, 0.08) 59%, transparent 60%),
    radial-gradient(60% 40% at 72% 82%, rgba(14, 165, 233, 0.22), transparent 70%);
  pointer-events: none;
}

.psec-frame-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(30, 58, 95, 0.8), transparent 82%);
  pointer-events: none;
}

.psec-frame-card {
  position: relative;
  background: rgba(248, 250, 252, 0.9);
  backdrop-filter: blur(12px);
  border-radius: 16px;
  padding: 28px;
  max-width: 340px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.18);
  transition: transform 400ms ease-out, box-shadow 400ms ease-out;
}

.psec-frame-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 32px 80px rgba(15, 23, 42, 0.24);
}

.psec-frame-title {
