}

@keyframes psec-cue {
  0%, 100% { opacity: 0.2; }
  50% { opacity: 1; }
}

.psec-frame--band {
  background: linear-gradient(to bottom, #12253e 0%, var(--psec-navy) 35%, var(--psec-sky) 100%);
