/* -- 布局实演：画布 + 步骤 -- */

.scr-intro p {
  max-width: 62em;
}

.scr-stage {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 24px;
  margin-top: 32px;
}

.scr-canvas {
  background: var(--scr-ink);
  border-radius: 8px;
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.scr-bars {
  display: flex;
  align-items: flex-end;
  gap: 20px;
  height: 190px;
}

.scr-bar {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 8px;
  height: 100%;
  text-align: center;
}

.scr-bar i {
  display: block;
  height: var(--h, 30%);
  background: rgba(247, 245, 240, 0.28);
  border-radius: 3px 3px 0 0;
  transition: background 400ms ease, transform 400ms ease;
}

.scr-bars[data-step="1"] .scr-bar:nth-child(1) i,
.scr-bars[data-step="2"] .scr-bar:nth-child(-n+2) i,
.scr-bars[data-step="3"] .scr-bar:nth-child(-n+3) i {
  background: var(--scr-blue);
}

.scr-bars[data-step="3"] .scr-bar:nth-child(3) i {
  background: var(--scr-red);
}

.scr-bar b {
  font-family: var(--scr-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  color: rgba(247, 245, 240, 0.5);
}

.scr-canvas-label {
  font-family: var(--scr-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  color: rgba(247, 245, 240, 0.5);
  margin-top: 16px;
}

.scr-steps {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.scr-step {
  border-left: 2px solid var(--scr-blue);
  padding: 4px 0 4px 24px;
  min-height: 96px;
  opacity: 0.3;
  transition: opacity 400ms ease;
}

.scr-step.is-current {
  opacity: 1;
}

.scr-step-no {
  display: block;
  font-family: var(--scr-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  color: var(--scr-blue);
  margin-bottom: 8px;
}

.scr-step-title {
  font-size: 24px;
  font-weight: 600;
  margin: 0 0 8px;
}

.scr-step-text {
  font-size: 17px;
  line-height: 1.6;
  color: rgba(247, 245, 240, 0.7);
  max-width: 28rem;
  margin: 0;
}

.scr-val {
  font-family: var(--scr-mono);
  font-size: 13px;
  color: var(--scr-blue);
}

.scr-rail {
  position: absolute;
  right: -26px;
  top: 50%;
  transform: translateY(-50%);
  width: 2px;
  height: 40vh;
  background: rgba(247, 245, 240, 0.15);
}

.scr-rail-fill {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 33%;
  background: var(--scr-blue);
  transition: height 400ms ease;
}

.scr-rail-no {
  position: absolute;
  top: 100%;
  left: 12px;
  margin-top: 8px;
  font-family: var(--scr-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  color: rgba(247, 245, 240, 0.6);
  white-space: nowrap;
}

.scr-btn {
  display: inline-block;
  background: var(--scr-blue);
  border: none;
  border-radius: 6px;
  color: #ffffff;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 20px;
  cursor: pointer;
  transition: background 200ms ease, transform 200ms ease;
}

.scr-btn:hover {
  background: #2560d4;
}

.scr-btn:active {
  transform: scale(0.98);
}

.scr-btn:focus-visible {
  outline: 2px solid rgba(47, 111, 237, 0.5);
  outline-offset: 2px;
}

.scr-specimen-title {
  font-weight: 700;
  font-size: 26px;
  letter-spacing: -0.02em;
}

.scr-specimen-label {
  font-family: var(--scr-mono);
  font-size: 12px;
  letter-spacing: 0.14em;
  color: var(--scr-blue);
}

@media (max-width: 900px) {
  .scr-stage {
    grid-template-columns: 1fr;
  }

  .scr-rail {
    display: none;
  }
}

