  position: relative;
  display: block;
  height: 100%;
  background: linear-gradient(to right, var(--hud-cyan), var(--hud-bright));
}

.hud-scanbar-fill::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -24px;
  width: 24px;
  background: rgba(255, 255, 255, 0.4);
  animation: hud-sweep 3s linear infinite;
}

@keyframes hud-sweep {
  to { left: calc(100% + 24px); }
}

.hud-scan-row {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 4px;
  font-family: var(--hud-mono);
