.ktyp-stagger span {
  display: inline-block;
  transform: translateY(110%);
  opacity: 0;
  animation: ktyp-rise 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ktyp-stagger span:nth-child(1) { animation-delay: 0ms; }
.ktyp-stagger span:nth-child(2) { animation-delay: 35ms; }
.ktyp-stagger span:nth-child(3) { animation-delay: 70ms; }
