.ktyp-stagger span:nth-child(5) { animation-delay: 140ms; }
.ktyp-stagger span:nth-child(6) { animation-delay: 175ms; }
.ktyp-stagger span:nth-child(7) { animation-delay: 210ms; }

@keyframes ktyp-rise {
  to { transform: translateY(0); opacity: 1; }
}

.ktyp-marquee {
  overflow: hidden;
  white-space: nowrap;
  border-top: 1px solid rgba(244, 241, 235, 0.14);
