/* -- hero：录像面板演示 -- */

.vhs-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 32px;
  align-items: center;
  margin-bottom: 80px;
}

.vhs-hero-copy p {
  margin-bottom: 16px;
}

.vhs-panel {
  position: relative;
  background: var(--vhs-violet);
  border: 1px solid rgba(255, 0, 255, 0.25);
  border-radius: 4px;
  padding: 24px;
  overflow: hidden;
  transition: border-color 180ms steps(3);
}

.vhs-panel:hover {
  border-color: rgba(255, 0, 255, 0.5);
}

.vhs-panel::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -100%;
  width: 2px;
  height: 100%;
  background: rgba(255, 255, 255, 0.3);
  opacity: 0;
  transition: left 180ms steps(3), opacity 180ms steps(3);
}

.vhs-panel:hover::after {
  left: 100%;
  opacity: 1;
}

.vhs-rec {
  position: absolute;
  top: 14px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--vhs-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  color: var(--vhs-green);
}

.vhs-rec i {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--vhs-green);
  animation: vhs-rec-blink 1s steps(2) infinite;
}

@keyframes vhs-rec-blink {
  50% { opacity: 0; }
}

.vhs-osd {
  position: absolute;
  top: 14px;
  right: 16px;
  font-family: var(--vhs-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  color: var(--vhs-yellow);
}

.vhs-osd--static {
  position: static;
  display: inline-block;
}

.vhs-panel-title {
  font-family: var(--vhs-mono);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--vhs-magenta);
  text-shadow: 2px 0 rgba(0, 255, 255, 0.55), -2px 0 rgba(255, 0, 255, 0.55);
  animation: vhs-jitter 8s steps(3) infinite;
  margin: 26px 0 10px;
}

@keyframes vhs-jitter {
  0%, 90%, 100% { transform: translateX(0); text-shadow: 2px 0 rgba(0, 255, 255, 0.55), -2px 0 rgba(255, 0, 255, 0.55); }
  92% { transform: translateX(-2px); text-shadow: 4px 0 rgba(0, 255, 255, 0.7), -4px 0 rgba(255, 0, 255, 0.7); }
  95% { transform: translateX(2px); }
}

.vhs-panel-text {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.8);
  margin: 0 0 20px;
}

.vhs-btn {
  background: transparent;
  border: 1px solid rgba(255, 0, 255, 0.4);
  border-radius: 2px;
  color: var(--vhs-magenta);
  font-family: var(--vhs-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  padding: 10px 24px;
  text-shadow: 0 0 8px rgba(255, 0, 255, 0.55);
  cursor: pointer;
  transition: all 80ms linear;
}

.vhs-btn:hover {
  border-color: var(--vhs-magenta);
  color: var(--vhs-yellow);
  text-shadow: 0 0 8px rgba(255, 255, 0, 0.55);
}

.vhs-btn:active {
  transform: translateX(2px);
  filter: hue-rotate(20deg);
}

.vhs-specimen-title {
  font-family: var(--vhs-mono);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-shadow: 2px 0 rgba(0, 255, 255, 0.5), -2px 0 rgba(255, 0, 255, 0.5);
}

@media (max-width: 900px) {
  .vhs-hero {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .vhs-rec i,
  .vhs-panel-title {
    animation: none;
  }
}

