/* ============================ 构成主义 ============================ */

.style-body.cstm {
  --cstm-red: #cc0000;
  --cstm-ink: #1a1a1a;
  --cstm-paper: #f2e8d5;
  --cstm-gold: #d4a843;
  --cstm-ochre: #8b4513;
  background: var(--cstm-paper);
  color: var(--cstm-ink);
}

.style-body.cstm h1,
.style-body.cstm h2,
.style-body.cstm h3 {
  font-weight: 900;
  text-transform: uppercase;
  color: var(--cstm-ink);
}

.style-body.cstm h2 {
  border-bottom: 4px solid var(--cstm-ink);
  padding-bottom: 8px;
}

.style-body.cstm .style-kicker {
  color: var(--cstm-red);
  font-weight: 900;
  letter-spacing: 0.04em;
}

.style-body.cstm .style-card-en {
  color: var(--cstm-red);
}

.style-body.cstm .style-card-tags span {
  border-radius: 0;
  background: var(--cstm-paper);
  border: 3px solid var(--cstm-ink);
  color: var(--cstm-ink);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.04em;
}

.style-body.cstm .swatch-chip {
  border-radius: 0;
  border: 3px solid var(--cstm-ink);
  box-shadow: 4px 4px 0 var(--cstm-ink);
}

.style-body.cstm code {
  border-radius: 0;
  background: var(--cstm-ink);
  border: none;
  color: var(--cstm-paper);
  font-weight: 900;
}

.style-body.cstm .style-table {
  background: var(--cstm-paper);
  border: 4px solid var(--cstm-ink);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--cstm-ink);
}

.style-body.cstm .style-table th {
  background: var(--cstm-red);
  color: var(--cstm-paper);
  font-weight: 900;
  text-transform: uppercase;
  border-bottom: none;
}

.style-body.cstm .style-table td {
  border-top: 2px solid var(--cstm-ink);
}

.style-body.cstm .specimen-meta,
.style-body.cstm .style-body-note {
  color: rgba(26, 26, 26, 0.7);
}

.style-body.cstm .type-specimen {
  background: var(--cstm-paper);
  border: 4px solid var(--cstm-ink);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--cstm-ink);
}

.style-body.cstm .dos-donts {
  background: var(--cstm-paper);
  border: 4px solid var(--cstm-ink);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--cstm-ink);
}

.style-body.cstm .dos-donts li::before {
  color: var(--cstm-red);
}

.style-body.cstm .dos-donts > div:last-child li::before {
  color: var(--cstm-ink);
}

.style-body.cstm .takeaway-preview {
  background: var(--cstm-paper);
  border: 4px solid var(--cstm-ink);
  border-radius: 0;
  color: var(--cstm-ink);
}

.style-body.cstm .lang-toggle button {
  background: var(--cstm-paper);
  border: 3px solid var(--cstm-ink);
  border-radius: 0;
  color: var(--cstm-ink);
  font-weight: 900;
  transition: all 100ms linear;
}

.style-body.cstm .lang-toggle button[aria-pressed="true"] {
  background: var(--cstm-ink);
  color: var(--cstm-paper);
}

.style-body.cstm .takeaway-copy,
.style-body.cstm .source-button {
  border-radius: 0;
  font-weight: 900;
  transition: all 100ms linear;
}

/* -- hero：斜切版面演示 -- */

.cstm-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 32px;
  align-items: center;
  margin-bottom: 96px;
}

.cstm-hero-copy p {
  margin-bottom: 16px;
}

.cstm-demo {
  position: relative;
  padding-top: 20px;
}

.cstm-plane {
  position: absolute;
  top: -10px;
  left: -40px;
  width: 150px;
  height: 150px;
  background: var(--cstm-red);
  border: 4px solid var(--cstm-ink);
  transform: rotate(-6deg) skewX(3deg);
  z-index: 0;
}

.cstm-card {
  position: relative;
  z-index: 1;
  background: var(--cstm-paper);
  border: 4px solid var(--cstm-ink);
  padding: 24px;
  box-shadow: 4px 4px 0 var(--cstm-ink);
}

.cstm-card-label {
  font-size: 16px;
