  color: var(--cstm-ochre);
  margin: 0 0 12px;
}

.cstm-card-title {
  font-size: 44px;
  font-weight: 900;
  line-height: 0.92;
  letter-spacing: -0.03em;
  transform: rotate(-3deg);
