  margin: 0 0 14px;
}

.cstm-card-text {
  font-size: 16px;
  font-weight: 900;
  margin: 0 0 22px;
}

.cstm-btn {
  display: inline-block;
  background: var(--cstm-red);
  border: 4px solid var(--cstm-ink);
  border-radius: 0;
  color: var(--cstm-paper);
  font-weight: 900;
  font-size: 16px;
  text-transform: uppercase;
  padding: 12px 28px;
  box-shadow: 4px 4px 0 var(--cstm-ink);
  cursor: pointer;
  transition: all 100ms linear;
}

.cstm-btn:hover {
  background: var(--cstm-ink);
  color: var(--cstm-paper);
  box-shadow: 8px 8px 0 var(--cstm-ink);
}

.cstm-btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.cstm-specimen-title {
