/* ============================ 印度节庆 ============================ */

.style-body.fest {
  --fest-vermilion: #e63946;
  --fest-ivory: #fff8e7;
  --fest-saffron: #ff9f1c;
  --fest-gold: #d4af37;
  --fest-violet: #7b2d8e;
  --fest-teal: #2a9d8f;
  --fest-serif: 'Cormorant Garamond', Georgia, 'Songti SC', serif;
  background: var(--fest-ivory);
  color: #5a4a3a;
}

.style-body.fest h1,
.style-body.fest h2,
.style-body.fest h3 {
  font-family: var(--fest-serif);
  color: var(--fest-vermilion);
  letter-spacing: 0.02em;
}

.style-body.fest h2 {
  border-bottom: 2px solid rgba(212, 175, 55, 0.6);
  padding-bottom: 10px;
}

.style-body.fest .style-kicker {
  color: var(--fest-saffron);
  font-family: var(--fest-serif);
  letter-spacing: 0.16em;
}

.style-body.fest .style-card-en {
  color: var(--fest-vermilion);
}

.style-body.fest .style-card-tags span {
  border-radius: 12px;
  background: rgba(212, 175, 55, 0.16);
  border: none;
  color: var(--fest-vermilion);
  font-family: var(--fest-serif);
  font-weight: 700;
  letter-spacing: 0.08em;
}

.style-body.fest .swatch-chip {
  border-radius: 12px;
  border: none;
  box-shadow: 0 0 14px rgba(212, 175, 55, 0.4);
}

.style-body.fest code {
  border-radius: 8px;
  background: rgba(212, 175, 55, 0.16);
  border: none;
  color: var(--fest-vermilion);
}

.style-body.fest .style-table {
  background: #ffffff;
  border: 1px solid rgba(212, 175, 55, 0.5);
  border-radius: 12px;
  box-shadow: 0 0 20px rgba(212, 175, 55, 0.28);
}

.style-body.fest .style-table th {
  background: var(--fest-vermilion);
  color: var(--fest-ivory);
  font-family: var(--fest-serif);
  font-weight: 700;
  border-bottom: none;
}

.style-body.fest .style-table td {
  border-top: 1px solid rgba(212, 175, 55, 0.4);
}

.style-body.fest .specimen-meta,
.style-body.fest .style-body-note {
  color: rgba(90, 74, 58, 0.72);
}

.style-body.fest .type-specimen {
  background: #ffffff;
  border: 1px solid rgba(212, 175, 55, 0.5);
  border-radius: 12px;
  box-shadow: 0 0 20px rgba(212, 175, 55, 0.28);
}

.style-body.fest .dos-donts {
  background: #ffffff;
  border: 1px solid rgba(212, 175, 55, 0.5);
  border-radius: 12px;
  box-shadow: 0 0 20px rgba(212, 175, 55, 0.28);
}

.style-body.fest .dos-donts li::before {
  color: var(--fest-vermilion);
}

.style-body.fest .dos-donts > div:last-child li::before {
  color: var(--fest-teal);
}

.style-body.fest .takeaway-preview {
  background: #ffffff;
  border: 1px solid rgba(212, 175, 55, 0.5);
  border-radius: 12px;
  color: rgba(90, 74, 58, 0.88);
}

.style-body.fest .lang-toggle button {
  background: transparent;
  border: 1px solid rgba(212, 175, 55, 0.55);
  border-radius: 12px;
  color: var(--fest-vermilion);
  font-family: var(--fest-serif);
  font-weight: 700;
  transition: all 250ms ease-out;
}

.style-body.fest .lang-toggle button[aria-pressed="true"] {
  background: var(--fest-vermilion);
  border-color: var(--fest-vermilion);
  color: var(--fest-ivory);
}

.style-body.fest .takeaway-copy,
.style-body.fest .source-button {
  border-radius: 12px;
  font-family: var(--fest-serif);
  font-weight: 700;
  letter-spacing: 0.08em;
}

/* -- hero：曼陀罗卡演示 -- */

.fest-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 48px;
  align-items: center;
  margin-bottom: 96px;
}

.fest-hero-copy p {
  margin-bottom: 16px;
}

.fest-card {
  position: relative;
  background: #ffffff;
  border: 1px solid rgba(212, 175, 55, 0.5);
  border-radius: 12px;
  padding: 32px;
  text-align: center;
  box-shadow: 0 0 20px rgba(212, 175, 55, 0.35);
}

.fest-mandala {
  position: relative;
  display: block;
  width: 120px;
  height: 120px;
  margin: 0 auto 20px;
}

.fest-mandala i {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(212, 175, 55, 0.9);
  border-radius: 999px;
}

.fest-mandala i:last-child {
  inset: 22%;
  border-color: var(--fest-vermilion);
  background: rgba(230, 57, 70, 0.1);
}

.fest-mandala::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 10px;
  height: 10px;
  transform: translate(-50%, -50%);
  border-radius: 999px;
  background: var(--fest-vermilion);
  box-shadow: 0 0 12px rgba(230, 57, 70, 0.7);
}

.fest-card-title {
  font-family: var(--fest-serif);
  font-size: 36px;
  font-weight: 700;
  color: var(--fest-vermilion);
  margin: 0 0 12px;
}

.fest-card-text {
  font-family: var(--fest-serif);
  font-size: 17px;
  line-height: 1.7;
  color: #5a4a3a;
  margin: 0 0 24px;
}

.fest-btn {
  display: inline-block;
  background: var(--fest-vermilion);
  border: 1px solid rgba(212, 175, 55, 0.6);
  border-radius: 12px;
  color: var(--fest-ivory);
  font-family: var(--fest-serif);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.16em;
  padding: 14px 32px;
  box-shadow: 0 0 20px rgba(212, 175, 55, 0.35);
  cursor: pointer;
  transition: all 250ms ease-out;
}

.fest-btn:hover {
  background: var(--fest-saffron);
  border-color: var(--fest-gold);
}

.fest-btn:active {
  transform: scale(0.98);
}

.fest-lamp {
  position: absolute;
  right: 28px;
  bottom: 24px;
  width: 44px;
  height: 26px;
  border-radius: 40% 40% 50% 50%;
  background: var(--fest-vermilion);
}

.fest-lamp::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 22px;
  width: 14px;
  height: 18px;
  transform: translateX(-50%);
  border-radius: 50% 50% 50% 50% / 70% 70% 30% 30%;
  background: radial-gradient(circle at 50% 70%, #ffd700, var(--fest-saffron));
  box-shadow: 0 0 16px rgba(255, 159, 28, 0.6);
}

.fest-specimen-title {
  font-family: var(--fest-serif);
  font-size: 32px;
  font-weight: 700;
}

@media (max-width: 900px) {
  .fest-hero {
    grid-template-columns: 1fr;
  }
}

/* -- 目录缩略图 -- */

.style-card .fest-thumb {
  background: var(--fest-ivory);
}

.fest-thumb-card {
  display: block;
  width: 68%;
  background: #ffffff;
  border: 1px solid rgba(212, 175, 55, 0.55);
  border-radius: 12px;
  padding: 20px 14px 14px;
  box-shadow: 0 0 16px rgba(212, 175, 55, 0.35);
  text-align: center;
}

.fest-thumb-mandala {
  display: block;
  width: 38px;
  height: 38px;
  margin: 0 auto 10px;
  border-radius: 999px;
  border: 1px solid rgba(212, 175, 55, 0.9);
  box-shadow: inset 0 0 0 8px rgba(230, 57, 70, 0.12);
}

.fest-thumb-title {
  display: block;
  height: 7px;
  width: 60%;
  margin: 0 auto 8px;
  background: rgba(230, 57, 70, 0.6);
}

.fest-thumb-text {
  display: block;
  height: 4px;
  margin: 0 auto 8px;
  background: rgba(90, 74, 58, 0.28);
}

.fest-thumb-text:last-of-type {
  width: 48%;
}

.fest-thumb-btn {
  display: block;
  width: 46%;
  height: 14px;
  margin: 0 auto;
  border-radius: 8px;
  background: var(--fest-vermilion);
}
/* ============================ 非洲纺织 ============================ */

