}

.style-body.aftex .style-table td {
  border-top: 1px solid rgba(240, 199, 94, 0.25);
}

.style-body.aftex .specimen-meta,
.style-body.aftex .style-body-note {
  color: rgba(232, 213, 181, 0.6);
}

.style-body.aftex .type-specimen {
  background: rgba(232, 213, 181, 0.08);
  border: 2px solid rgba(240, 199, 94, 0.4);
  border-radius: 8px;
  box-shadow: none;
}

.style-body.aftex .dos-donts {
  background: rgba(232, 213, 181, 0.08);
  border: 2px solid rgba(240, 199, 94, 0.4);
  border-radius: 8px;
