}

.style-body.aftex .dos-donts li::before {
  color: var(--aftex-gold);
}

.style-body.aftex .dos-donts > div:last-child li::before {
  color: var(--aftex-orange);
}

.style-body.aftex .takeaway-preview {
  background: rgba(232, 213, 181, 0.08);
  border: 2px solid rgba(240, 199, 94, 0.4);
  border-radius: 8px;
  color: rgba(232, 213, 181, 0.85);
}

.style-body.aftex .lang-toggle button {
  background: transparent;
  border: 2px solid rgba(240, 199, 94, 0.4);
  border-radius: 6px;
  color: var(--aftex-gold);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.1em;
  transition: all 120ms linear;
}

.style-body.aftex .lang-toggle button[aria-pressed="true"] {
  background: var(--aftex-orange);
  border-color: var(--aftex-orange);
  color: var(--aftex-sand);
}

.style-body.aftex .takeaway-copy,
.style-body.aftex .source-button {
  border-radius: 6px;
  font-weight: 900;
  letter-spacing: 0.1em;
  transition: all 120ms linear;
}

