  bottom: 0;
  left: 16%;
  width: 42%;
  height: 52%;
  background: var(--cub-slate);
  clip-path: polygon(0 12%, 92% 0, 100% 88%, 8% 100%);
}

.cub-frag--d {
  bottom: 0;
  right: 4%;
  width: 36%;
  height: 46%;
  background: var(--cub-brick);
  clip-path: polygon(10% 0, 100% 14%, 86% 100%, 0 82%);
}

