/* -- hero：分组卡与快捷操作 -- */

.pui-hero {
  max-width: 480px;
  margin-bottom: 96px;
}

.pui-card {
  position: relative;
  border-radius: 24px;
  border: 1px solid rgba(102, 80, 143, 0.1);
  padding: 20px;
  margin-bottom: 12px;
  box-shadow: 0 4px 12px rgba(102, 80, 143, 0.1);
}

.pui-card--mint {
  background: var(--pu-mint);
}

.pui-card--lilac {
  background: var(--pu-lilac);
}

.pui-tag {
  margin: 0 0 8px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(102, 80, 143, 0.7);
}

.pui-card-title {
  margin: 0 0 8px;
  font-size: 21px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--pu-ink);
}

.pui-card-body {
  margin: 0;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.55;
  color: rgba(51, 45, 61, 0.8);
}

.pui-cluster {
  display: flex;
  gap: 12px;
  margin-top: 16px;
}

.pui-act {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  border: none;
  padding: 0;
  cursor: pointer;
}

.pui-act--lilac {
  background: rgba(217, 199, 255, 0.3);
}

.pui-act--mint {
  background: rgba(203, 239, 223, 0.3);
}

.pui-act--coral {
  background: rgba(255, 181, 167, 0.3);
}

.pui-field {
  margin: 12px 0;
}

.pui-input {
  width: 100%;
  background: var(--pu-cream);
  color: var(--pu-ink);
  border: 1px solid rgba(102, 80, 143, 0.2);
  border-radius: 16px;
  padding: 12px 16px;
  font-family: var(--pu-sans);
  font-size: 15px;
  transition: box-shadow 150ms ease, border-color 150ms ease;
}

.pui-input::placeholder {
  color: rgba(51, 45, 61, 0.6);
}

.pui-input:focus {
  outline: none;
  border-color: rgba(102, 80, 143, 0.2);
  box-shadow: 0 0 0 4px rgba(255, 181, 167, 0.4);
}

.pui-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 12px 20px;
  background: var(--pu-violet);
  color: #ffffff;
  font-family: var(--pu-sans);
  font-size: 15px;
  font-weight: 600;
  border-radius: 16px;
  border: none;
  text-decoration: none;
  box-shadow: 0 6px 16px rgba(102, 80, 143, 0.2);
  transition: all 200ms ease;
}

.pui-btn:hover {
  transform: translateY(-2px);
}

.pui-btn:active {
  transform: scale(0.98);
}

.pui-specimen-title {
  font-family: var(--pu-sans);
  font-size: 26px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -0.01em;
  margin: 0;
}

.pui-specimen-label {
  font-family: var(--pu-sans);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(102, 80, 143, 0.7);
  margin: 0;
}

/* -- 目录缩略图 -- */

.style-card .pui-thumb {
  background: var(--pu-cream);
}

.pui-thumb-card {
  background: var(--pu-mint);
  border-radius: 24px;
  border: 1px solid rgba(102, 80, 143, 0.1);
  padding: 12px;
  box-shadow: 0 4px 12px rgba(102, 80, 143, 0.1);
}

.pui-thumb-tag {
  display: block;
  height: 5px;
  width: 40%;
  background: rgba(102, 80, 143, 0.7);
  border-radius: 999px;
  margin-bottom: 8px;
}

.pui-thumb-title {
  display: block;
  height: 8px;
  width: 66%;
  background: var(--pu-ink);
  border-radius: 999px;
  margin-bottom: 8px;
}

.pui-thumb-text {
  display: block;
  height: 4px;
  background: rgba(51, 45, 61, 0.35);
  border-radius: 999px;
  margin-bottom: 5px;
}

.pui-thumb-text:last-of-type {
  width: 70%;
  margin-bottom: 0;
}

.pui-thumb-cluster {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.pui-thumb-dot {
  width: 20px;
  height: 20px;
  border-radius: 999px;
  background: rgba(217, 199, 255, 0.6);
}

.pui-thumb-dot:nth-child(2) {
  background: rgba(203, 239, 223, 0.6);
}

.pui-thumb-dot:nth-child(3) {
  background: rgba(255, 181, 167, 0.6);
}

