/* 舞台：左右各 40px 留给切换按钮，卡片最大 640px */
.cstack-stage {
  display: grid;
  grid-template-columns: 40px minmax(0, 640px) 40px;
  justify-content: center;
  align-items: center;
  gap: 24px;
  padding: 48px 0;
}

/* Deck Container：顶部留 48px 给后置层，所有卡共用一个格 */
.cstack-deck {
  display: grid;
  grid-template-areas: "stack";
  padding-top: 48px;
}

.cstack-card {
  grid-area: stack;
  align-self: start;
  padding: 32px;
  background: #ffffff;
  border-radius: 16px;
  transform: translateY(calc(var(--layer, 0) * -12px)) scale(calc(1 - var(--layer, 0) * 0.04));
  opacity: calc(1 - var(--layer, 0) * 0.3);
  z-index: calc(3 - var(--layer, 0));
  transition: transform .4s cubic-bezier(0.22, 1, 0.36, 1), opacity .4s cubic-bezier(0.22, 1, 0.36, 1);
}

.cstack-card[data-layer="0"] {
  box-shadow: 0 18px 40px rgba(26, 26, 46, 0.12);
}

.cstack-card:not([data-layer="0"]) {
  box-shadow: 0 8px 20px rgba(26, 26, 46, 0.08);
}

.cstack-tag {
  margin: 0 0 8px;
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #6c5ce7;
}

