  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  color: #8a8a99;
}

/* Deck Controls：圆形按钮 40px，hover 描边转午夜并起一层浅影 */
.cstack-nav {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  padding: 0;
  background: #ffffff;
  border: 1px solid #e4e4ec;
  border-radius: 999px;
  color: #1a1a2e;
  cursor: pointer;
  transition: border-color .15s ease-out, box-shadow .15s ease-out, transform .15s ease-out;
}

.cstack-nav svg {
  width: 16px;
  height: 16px;
}

.cstack-nav:hover {
  border-color: #1a1a2e;
  box-shadow: 0 4px 12px rgba(26, 26, 46, 0.08);
}

.cstack-nav:active {
  transform: scale(0.94);
}

.cstack-nav:focus-visible {
  outline: 2px solid #6c5ce7;
  outline-offset: 2px;
}

.cstack-action-row {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-top: 12px;
}

/* Step Indicator：8px 圆点，当前项拉长成 24px 靛蓝胶囊 */
