  display: flex;
  justify-content: center;
  gap: 8px;
}

.cstack-dot {
  width: 8px;
  height: 8px;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: rgba(26, 26, 46, 0.3);
  cursor: pointer;
  transition: width .3s ease-out, background-color .3s ease-out;
}

