  .cstack-stage {
    grid-template-columns: 40px minmax(0, 1fr) 40px;
    gap: 12px;
  }

  .cstack-card:not([data-layer="0"]) {
    display: none;
  }

  .cstack-card {
    padding: 24px;
  }
}

