}

.mgrid-stage {
  padding: 24px;
  border: 1px dashed #d4d4d4;
  border-radius: 8px;
  background: #ffffff;
}

/* 主网格：grid-template-areas 显式定义版面 */
.mgrid-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-template-areas:
    "lead  lead  story story"
    "lead  lead  brief quote"
    "deep  deep  brief quote";
  gap: 24px;
}

.mgrid-grid > *:nth-child(1) {
  grid-area: lead;
}

.mgrid-grid > *:nth-child(2) {
  grid-area: story;
}

.mgrid-grid > *:nth-child(3) {
  grid-area: brief;
}

.mgrid-grid > *:nth-child(4) {
  grid-area: quote;
}

.mgrid-grid > *:nth-child(5) {
  grid-area: deep;
}

/* Section Label：12px 全大写、0.1em 字距，颜色按栏目固定 */
