  margin: 0 0 8px;
  font-family: Inter, system-ui, "Segoe UI", sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.mgrid-label--red {
  color: #e63946;
}

.mgrid-label--teal {
  color: #2a9d8f;
}

.mgrid-label--navy {
  color: #264653;
}

.mgrid-label--ink {
  color: #1a1a1a;
}

/* Lead Block：2×2 头条，16:9 大图 + 40px 衬线标题 + 20px 导语 */
.mgrid-lead {
  padding: 24px;
