}

.mgrid-standfirst {
  margin: 0 0 16px;
  font-size: 20px;
  line-height: 1.4;
  color: #3c3c3c;
}

/* 图片：固定比例、4px 圆角、裁切不拉伸 */
.mgrid-figure {
  margin: 0;
  overflow: hidden;
  border-radius: 4px;
  background: #eeeeee;
}

.mgrid-figure img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.mgrid-figure--lead {
  aspect-ratio: 16 / 9;
}

.mgrid-figure--wide {
  aspect-ratio: 4 / 3;
  margin-bottom: 12px;
}

/* Brick Block：次条与短讯 */
.mgrid-brick {
  padding: 24px;
  background: #ffffff;
  border: 1px solid #e8e8e8;
  border-radius: 8px;
}

.mgrid-brick-title {
