}

.mgrid-brick--tall .mgrid-brick-title:hover {
  color: #1a1a1a;
}

.mgrid-brick-body {
  margin: 0;
  font-size: 15px;
  line-height: 1.7;
  color: #3c3c3c;
}

/* Pull Quote：金色底、28px 衬线斜体 */
