  color: #ffffff;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: border-color .2s ease-out, background-color .2s ease-out;
}

.hfull-nav-cta:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: #ffffff;
}

/* 标题区：96px、两行封顶 */
.hfull-copy {
  position: absolute;
  top: 132px;
  left: 32px;
  right: 32px;
  max-width: 1100px;
}

.hfull-title {
  margin: 0 0 16px;
  font-family: Inter, -apple-system, "Segoe UI", system-ui, "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: clamp(44px, 6.4vw, 96px);
  font-weight: 700;
  line-height: 0.98;
  letter-spacing: -0.035em;
  color: #ffffff;
}

.hfull-sub {
  margin: 0;
  font-size: 24px;
  line-height: 1.3;
  color: rgba(255, 255, 255, 0.8);
}

.hfull-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 32px 0 0;
}

/* Hero CTA：白底黑字、999px 全圆角 */
.hfull-cta {
  padding: 16px 32px;
  background: #ffffff;
  border: none;
  border-radius: 999px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
  color: #000000;
  font-family: Inter, -apple-system, "Segoe UI", system-ui, sans-serif;
  font-size: 18px;
  font-weight: 600;
  cursor: pointer;
  transition: transform .2s ease-out, box-shadow .2s ease-out, background-color .2s ease-out, border-color .2s ease-out;
}

.hfull-cta:hover {
  background: rgba(255, 255, 255, 0.95);
  transform: translateY(-4px);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.5);
}

.hfull-cta:active {
  transform: scale(0.98);
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
}

.hfull-cta:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.8);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px rgba(0, 0, 0, 0.6);
}

.hfull-cta--ghost {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow: none;
  color: #ffffff;
}

.hfull-cta--ghost:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: #ffffff;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.5);
}

/* Frosted Feature Card：白 10% 填充 + 8px 模糊 */
.hfull-features {
  position: absolute;
  left: 32px;
  right: 32px;
  bottom: 32px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}

.hfull-card {
  padding: 24px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 16px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: transform .3s ease-out, box-shadow .3s ease-out, background-color .3s ease-out, border-color .3s ease-out;
}

.hfull-card:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
  transform: translateY(-8px);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.5);
}

.hfull-card-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin-bottom: 16px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
  transition: transform .3s ease-out;
}

.hfull-card-icon svg {
  width: 22px;
  height: 22px;
}

.hfull-card:hover .hfull-card-icon {
  transform: scale(1.1);
}

.hfull-card-title {
  margin: 0 0 6px;
  font-size: 16px;
  font-weight: 600;
  color: #ffffff;
}

.hfull-card-body {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.72);
}

@media (max-width: 900px) {
  .hfull-hero {
    height: 640px;
  }

  .hfull-features {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .hfull-card {
    padding: 16px;
  }

  .hfull-card-icon {
    width: 36px;
    height: 36px;
    margin-bottom: 8px;
  }

  .hfull-sub {
    font-size: 18px;
  }
}

/* 目录缩略卡：一屏画面压成一个小方块 */
.style-card .hfull-thumb {
  position: relative;
  display: grid;
  align-content: center;
  gap: 10px;
  padding: 24px 30px;
  background: #0a0a0a;
  overflow: hidden;
}

.hfull-thumb-title {
  width: 74%;
  height: 12px;
  border-radius: 3px;
  background: #ffffff;
}

.hfull-thumb-sub {
  width: 46%;
  height: 7px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.35);
}

.hfull-thumb-cta {
  width: 58px;
  height: 16px;
  border-radius: 999px;
  background: #ffffff;
}

.hfull-thumb-glow {
  position: absolute;
  right: -30px;
  top: -40px;
  width: 150px;
  height: 150px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(108, 92, 231, 0.55), transparent 70%);
}
